const version = "14.0.6";
try {
  if (args[0]?.macroPass === "DamageBonus") {
    if (!workflow?.hitTargets?.size) return {};
    return { damageRoll: "1d6[necrotic]", flavor: "Life Stealer" };
  }
  if (args[0]?.macroPass === "postActiveEffects") {
    if (!workflow?.hitTargets?.size) return;
    const necroticTotal = (workflow?.bonusDamageRolls ?? [])
      .reduce((sum, r) => sum + ((r.options?.type ?? r.options?.flavor) === "necrotic" ? r.total : 0), 0);
    if (!necroticTotal) return;
    const currentTemp = actor?.system?.attributes?.hp?.temp ?? 0;
    if (necroticTotal > currentTemp) {
      ChatMessage.create({ content: `${macroItem?.name ?? "Life Stealer"} steals ${necroticTotal} HP` });
      await actor.update({ "system.attributes.hp.temp": necroticTotal });
    }
  }
} catch (err) {
  console.error(`Life Stealer ${version}`, err);
}
